import{_ as o,o as i,c as d,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"插件示例","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/dev-guide/examples.md","filePath":"zh-CN/dev-guide/examples.md","lastUpdated":1785993908000}'),t={name:"zh-CN/dev-guide/examples.md"};function c(a,e,n,s,l,u){return i(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="插件示例" tabindex="-1">插件示例 <a class="header-anchor" href="#插件示例" aria-label="Permalink to &quot;插件示例&quot;">​</a></h1><p>Lertaro 自带两个插件，都是很有参考价值的真实案例——都在 Lertaro 仓库的 <code>Plugins/</code> 目录下。</p><h2 id="coreextensions-——-动作与-shell-右键菜单" tabindex="-1">CoreExtensions —— 动作与 Shell 右键菜单 <a class="header-anchor" href="#coreextensions-——-动作与-shell-右键菜单" aria-label="Permalink to &quot;CoreExtensions —— 动作与 Shell 右键菜单&quot;">​</a></h2><p><code>CoreExtensionsPlugin</code> 同时实现了三个接口:<code>IPlugin</code>、<code>IActionProvider</code>、<code>IConfigurable</code>。</p><ul><li><strong><code>IActionProvider.GetActions()</code></strong> 返回十个内置的 <code>ISearchResultAction</code>——打开、在资源管理器中定位、复制路径、复制/剪切文件本身、在其所在位置打开命令提示符、touch/mkdir，以及打开和命令提示符的提权(以管理员身份运行)变体。</li><li><strong><code>IActionProvider.GetDynamicActionProviders()</code></strong> 返回一个 <code>IDynamicActionProvider</code>—— <code>ShellMenuActionProvider</code>——正是它让真正的 Windows 右键菜单(包括&quot;发送到&quot;这类级联子菜单)出现在 Lertaro 自己的动作菜单里。如果你想在 Lertaro 里呈现<em>任何</em>外部、动态构建的菜单，而不是一份固定的动作列表，这是值得照抄的模式。</li><li><strong><code>IConfigurable.GetConfigSchema()</code></strong> 展示了带嵌套字段分组和 <code>StringList</code> 字段类型的配置模式 ——如果你的插件在设置 → 插件的配置对话框里需要的不只是一份扁平的布尔值列表，值得读一下这部分。</li><li>有五个提供器实现了 <a href="./sdk/ui-extensions.html#iquickpaneltabprovider"><code>IQuickPanelTabProvider</code></a>，而且它们正好覆盖了这个接口的两端。<code>FavoritesTabProvider</code> 和 <code>HistoryTabProvider</code> 原样交出一份内存里的列表——最简参考实现，因为两者自己都没有额外的状态。<code>WindowsRecentTabProvider</code> 则是另一端：它在后台任务上读目录、通过 COM 解析 shell 快捷方式，<strong>先</strong>截断再做那件昂贵的事，并给每个条目填上 <code>Metadata.Modified</code>，好让标签的「最新在前」真的有意义。</li><li><code>LastDirectoryTabProvider</code> 和 <code>RecentFilesTabProvider</code> 值得读的理由不太一样：它们自己压根没有数据，而是通过 <a href="./sdk/services.html"><code>ExplorerPathService</code></a> 和 <code>RecentFilesService</code> 向宿主要。只要你的插件想展示的东西 Lertaro 本来就知道，照抄这个模式就对了。</li></ul><h2 id="pinyinalias-——-中文文件名拼音别名" tabindex="-1">PinyinAlias —— 中文文件名拼音别名 <a class="header-anchor" href="#pinyinalias-——-中文文件名拼音别名" aria-label="Permalink to &quot;PinyinAlias —— 中文文件名拼音别名&quot;">​</a></h2><p><code>PinyinAliasProvider</code> 同时实现了 <code>IAliasProvider</code> 和 <code>ITranslationProvider</code>——一个插件可以自由组合多个相关的 SDK 角色，这是个很好的参考模板:</p><ul><li><strong><code>IAliasProvider.InputRanges</code>/<code>OutputRanges</code></strong> 直接复用 <code>PinyinEngine</code> 自己表里的边界来声明这两个字母表(<code>InputRanges</code>:CJK 区块;<code>OutputRanges</code>:<code>a</code>-<code>z</code>),不重复写魔数——宿主用它们支持 &quot;大cj&quot;匹配&quot;大长今&quot;这类混合了字面汉字和拼音的查询。</li><li><strong><code>IAliasProvider.CanHandle(text)</code></strong> 会先扫描是否存在任意中文字符，再决定要不要做实际工作，所以非中文文件名会完全跳过别名生成。</li><li><strong><code>IAliasProvider.GetAliases(text)</code></strong> 先构建一张按字符划分的音节表(每个汉字映射到它可能的拼音读音)，然后产出一个全拼别名和一个首字母别名。对于含多音字(有一种以上有效读音)的文件名，会为每种常见读音组合都生成别名——上限 32 种组合，防止极端输入引发组合爆炸——用 <code>|</code> 连接各个备选项，这样搜索引擎会把每一个都当作候选，而不是要求它们同时全部匹配。</li><li><strong><code>ITranslationProvider</code></strong> 实现在<em>同一个</em>类上，纯粹是为了给这个插件自己的界面文本(比如它的显示名称)提供翻译，通过 <code>TranslationService.LoadEmbeddedTranslations</code> 实现——这两个接口用途上并无关联，只是碰巧在这个体量很小的单文件插件里放在了同一个类型上。</li><li>用一个 <code>lock</code> 保护的 <code>Dictionary&lt;string, Dictionary&lt;string, string&gt;&gt;</code> 缓存避免了每次调用 <code>GetTranslations</code> 都重新解析内嵌的翻译 JSON——这是任何在 <code>GetTranslations</code> 里做了非平凡工作的插件都该采用的标准模式。</li></ul><p>把这两个插件对照着看，是理解<a href="./sdk/core-search-actions.html">插件 SDK 参考</a>里各个部分如何在实践中配合起来最快的方式。</p>',9)])])}const P=o(t,[["render",c]]);export{h as __pageData,P as default};
